const QI_VOCAB_SHORT = ['寒', '凉', '平', '温', '热', '微寒', '微温'];   // 通行词表，缺「大寒」
const QI_VOCAB_FULL  = [...QI_VOCAB_SHORT, '大寒'];                      // 补上

// 词表里没有的值读成 null —— 这就是「空值 = 解析缺口」
const qiByVocab = (vocab) =>
  drugsOf().map((d) => ({ name: d.name, qi: vocab.includes(d.nature.qi) ? d.nature.qi : null }));

// 名字带「化痰」不等于归肺
const withoutLung = () => drugsOf().filter((d) => !d.nature.guijing.includes('肺'));
```
